const t = $json || {};
const ex = t.execution || {};
const wf = t.workflow || {};
const err = ex.error || {};
const wfName = wf.name || 'unknown workflow';
const execId = ex.id != null ? String(ex.id) : null;
const execUrl = ex.url || null;
const lastNode = ex.lastNodeExecuted || '(unknown node)';
const errName = err.name || 'Error';
const errMsg = (err.message != null ? String(err.message) : 'no message').slice(0, 900);
const mode = ex.mode || '';

const run_log = {
  workflow_name: wfName,
  execution_id: execId,
  lead_id: null,
  status: 'failed',
  step_name: 'workflow_error',
  error_message: (errName + ': ' + errMsg).slice(0, 1000),
  metadata: { last_node: lastNode, error_name: errName, mode: mode, execution_url: execUrl }
};

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Workflow failure', emoji: false } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*Workflow:*\n' + wfName },
    { type: 'mrkdwn', text: '*Failed node:*\n' + lastNode },
    { type: 'mrkdwn', text: '*Error type:*\n' + errName },
    { type: 'mrkdwn', text: '*Execution:*\n' + (execId || '-') }
  ]},
  { type: 'section', text: { type: 'mrkdwn', text: '*Message:*\n```' + errMsg + '```' } }
];
if (execUrl) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: '<' + execUrl + '|Open execution>' }] });

const slack_body = {
  channel: '#automation-errors',
  text: 'Workflow failure in ' + wfName + ' (' + errName + ')',
  blocks: blocks
};

return [{ json: { run_log, slack_body } }];
